import sys
from fractions import Fraction
from math import comb

def pascal_triangle(n):
    triangle = [[0 for x in range(n+1)] for x in range(n+1)]
    for i in range(n+1):
        for j in range(i+1):
            if j == 0 or j == i:
                triangle[i][j] = 1
            else:
                triangle[i][j] = triangle[i-1][j-1] + triangle[i-1][j]
    return triangle

def generate_probability_matrix(n,m,p,mat):
    if n == 1:
        return mat
    dp = pascal_triangle(m+1)[0:n+1]
    for i in range(n):
        for j in range(m):
            for k in range(m):
                if p[i][k] != 0:
                    dp[i+1][j+k] += dp[i][j] * p[i][k]
    generate_probability_matrix(n-1, m, p, dp)

