def find_smallest_non_negative_integer(K):
    N = len(K)
    B = 10
    dp = [[0] * B for _ in range(N + 1)]
    dp[0][K[0]] = 1
    for i in range(1, N):
        for cumulative_sum in range(B):
            for last_digit in range(B):
                if dp[i - 1][cumulative_sum] > 0:
                    new_sum = cumulative_sum + K[i]
                    if new_sum < B: 
                        dp[i][new_sum] += dp[i - 1][cumulative_sum]
                    for possible_digit in range(B):
                        if cumulative_sum % B + K[i] * B + last_digit <= B:
                            dp[i][cumulative_sum % B + K[i] * B + last_digit] = (
                                (dp[i][cumulative_sum % B + K[i] * B + last_digit] +
                                dp[i - 1][cumulative_sum]) % MOD + 1) % MOD
    res = sum(dp[-1]) % MOD
