from collections import defaultdict

# Function to check if a given sequence is balanced
def is_balanced(sequence):
    balance = 0
    for char in sequence:
        if char == ')':
            balance -= 1
        else:
            balance += 1
        if balance < 0:
            return False
    return balance == 0

# Function to find a balanced sequence
def find_balanced_sequence(card_numbers):
    sequence = []
    for i, number in enumerate(card_numbers, start=1):
        if number > 0:
            sequence.append(f'{number} {i - (number + 1)}')
        else:
            sequence.append(f'-{number} {i - (number + 1)}')
    return sequence

# Main function to solve the problem
def solve(cards):
    max_positive = defaultdict(int)
    max_negative = defaultdict(int)

    # Count positive and negative numbers
    for card in cards:
        if card > 0:
            max_positive[card] = sum(max_positive.items(), [])
        else:
            max_negative[-card] = sum(max_negative.items(), [])

    # Check if there's both balanced positive and negative sequences
    has_balanced_pos = False
    has_balanced_neg = False
    for key, val in max_positive.items():
        if is_balanced(val):
            has_balanced_pos = val
            break

    for key, val in max_negative.items():
        if is_balanced(val):
            has_balanced_neg = val
            break

    if not has_balanced_pos or not has_balanced_neg:
        return "NO"

    # Constructs balanced front and back from positive and negative numbers respectively
    front = find_balanced_sequence(sorted([f'{k} {v}' for k, v in max_positive.items() if k < 0])[::-1])
    back = find_balanced_sequence(sorted([f'-{k} {v}' for k, v in max_negative.items() if k > 0])[::-1])

    return "YES\n" + "\n".join(front) + "\n" + "\n".join(back)

