from collections import deque

def add_road(current_road, x):
    result = []
    i = 0
    while i < len(current_road):
        if i < len(current_road) - 1 and abs(current_road[i]) + abs(current_road[i+1]) <= x:
            i += 1
            result.append((current_road[i] + x, i+1))
        elif i < len(current_road) - 2 and abs(current_road[i+1]) + abs(current_road[i+2]) <= x:
            i += 2
            result.append((current_road[i] + current_road[i+1], i+2))
        else:
            result.append((current_road[i], i))
        i += 1
    temp = deque(result)
    while len(temp) > 1:
        try:
            (a, b), (c, d) = temp.popleft(), temp.popleft()
            if abs(a) + abs(b) >= x:
                temp.append((a, c))
            else:
                temp.append((a + b, b))
        except IndexError:
            break
    return result, temp

def change_cargo(index, new_value, current_road):
    if len(current_road) == 1:
        return [(index, new_value)]
    result, temp = add_road(current_road, abs(new_value))
    i = 0
    while i < len(result):
        index, value = result[i]
        if index == new_value:
            del result[i - 1]
        elif value:
            index, infinite = value
            if infinite:
                continue
            result.append((index, value[1]))
        i += 1
