from typing import List

def is_balanced(front_sequence: List[int], back_sequence: List[int]):
    """
    Check if both sequences are balanced.
    """
    bracket_stack = []
    for number in front_sequence:
        if number > 0:
            bracket_stack.append(number)
        else:
            if not bracket_stack or -(number) != bracket_stack.pop():
                return False
    for number in back_sequence:
        if len(bracket_stack) == 0 and number > 0 or number < 0 < bracket_stack[-1]:
            return False
    return True

def can_balance_cards(front_cards: List[List[int]], back_cards: List[List[int]]):
    """
    Determine if it's possible to reorder the cards to have balanced front and back sequences.
    """
    n = len(front_cards)
    front_sequence = [0] * n
    back_sequence = [0] * n

    for i in range(n):
        if front_cards[i][0] > 0 and front_cards[i][1] > 0:
            front_sequence[i] = front_cards[i][0]
            back_sequence[i] = -front_cards[i][1]
        elif front_cards[i][0] < 0 and front_cards[i][1] < 0:
            front_sequence[i] = front_cards[i][0]
            back_sequence[i] = -front_cards[i][1]
        else:
            front_sequence[i] = front_cards[i][0]
            back_sequence[i] = -front_cards[i][1]
            front_sequence[i] = -front_cards[i][0]
            back_sequence[i] = front_cards[i][1]
        # Ensure balanced sequence during iteration to avoid making mistake in the end
        if is_balanced(front_sequence, back_sequence) == False:
            return False

    return True

def reorder_cards(front_cards: List[List[int]], back_cards: List[List[int]], order):
    return [front_cards[i] if j else back_cards[i] for i, j in enumerate(order)]

