    return count

def min_distinct_difference(a, queries):
    n = len(a)
    bucket_sizes = [0] * (100001)

    for i in range(n):
        bucket_sizes[a[i]] += 1

    a.sort()

    results = []

    for query in queries:
        if len(results) == 0:
            if query[0] == 1:
                l, r, k = query[1], query[2], query[3]
                if r - l + 1 < k or find_largest_bucket_size(a[l-1:r+1], a[l-1:r+1].count(a[l-1:r+1].max())) < k:
                    results.append(-1)
                else:
                    first_bucket = a[l-1:r+1].count(a[l-1:r+1].max())
                    results.append(find_largest_bucket_size(a[l-1:r+1], first_bucket + k - 1))
            elif query[0] == 2:
                p, x = query[1], query[2]
                if a[p-1] != x:
                    bucket_sizes[a[p-1]] -= 1
                    a[p-1] = x
                    bucket_sizes[a[p-1]] += 1
        else:
            if query[0] == 1:
                l, r, k = query[1], query[2], query[3]
                if r - l + 1 < k or find_largest_bucket_size(a[l-1:r+1], a[l-1:r+1].count(a[l-1:r+1].max())) < k:
                    results.append(-1)
                else:
                    first_bucket = find_largest_bucket_size(a[l-1:r+1], a[l-1:r+1].count(a[l-1:r+1].max()))
                    second_bucket = find_largest_bucket_size(a[l-1:r+1], first_bucket - k + 1)
                    res = (r - l + 1) // k
                    diff = max(second_bucket, k - res)
                    results.append(1 + diff)
            elif query[0] == 2:
                p, x = query[1], query[2]
                if a[p-1] != x:
                    bucket_sizes[a[p-1]] -= 1
                    a[p-1] = x
                    bucket_sizes[a[p-1]] += 1

    return results

