        self._sum = p // gcd(p, MOD - p)
        self._ran = 2
        if exclusive:
            self._ran += 1
        self._exp = pow(2, self._ran - 2, MOD)

    def reduced_sum(self, p):
        return (self._sum * p - 1 + MOD) % MOD

    def run(self, a, freq):
