def find_balanced_sequence(cards_count, cards):
    left_balance = defaultdict(int)
    right_balance = defaultdict(int)
    for i in range(2 * cards_count):
        card = cards[i]
        if card[1] == ' ':
            left_balance[card[0]] += 1
            right_balance[-card[0]] += 1
        else:
            left_balance[card[0]] -= 1
            right_balance[card[1]] -= 1

    for unique_number in range(-cards_count, cards_count):
        if left_balance[unique_number] * 2 != 0:
            return False
        if unique_number not in left_balance and unique_number * -1 not in right_balance:
            return False
        if unique_number not in right_balance and unique_number * -1 not in right_balance:
            return False

    if left_balance[-1] * 2 != 0:
        return False
    if right_balance[-cards_count] * 2 != 0:
        return False
    return True

