from collections import defaultdict

def find_parent(parent, i):
    if parent[i] == i:
        return i
    return find_parent(parent, parent[i])

def union(parent, rank, x, y):
    px = find_parent(parent, x)
    py = find_parent(parent, y)

    if px == py:
        return False
    if rank[px] > rank[py]:
        parent[py] = px
    elif rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        rank[px] += 1
    return True

