from collections import deque

def is_balanced_sequence(sequence, n):
    stack = []
    pairs = {
        '(': ')',
        '[': ']',
        '{': '}'
    }
    stack.extend(sequence)

    for number in pairs.values():
        while stack and stack[-1] == number:
            stack.pop()

    return len(stack) == 0

def reorder_cards(cards, n):
    sequence_front = deque()
    sequence_back = deque()

    for card in cards:
        front_number = card[0]
        back_number = card[1]

        if front_number in sequence_front and back_number in sequence_front:
            if sequence_front.index(front_number) < sequence_front.index(back_number):
                sequence_back.append(back_number)
            else:
                sequence_back.append(front_number)
        elif front_number in sequence_front and back_number not in sequence_front:
            sequence_back.append(front_number)
        elif back_number in sequence_back and front_number not in sequence_back:
            sequence_back.append(back_number)
        elif front_number not in sequence_front and back_number not in sequence_back:
            sequence_front.append(front_number)
            sequence_back.append(back_number)

        if not(is_balanced_sequence(sequence_front, n) and is_balanced_sequence(sequence_back, n)):
            return "NO"

    if not is_balanced_sequence(sequence_front, n) or not is_balanced_sequence(sequence_back, n):
        return "NO"

    return "YES\n" + "\n".join(map(str, sequence_front)) + "\n" + "\n".join(map(str, sequence_back))

