from math import comb, gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def mod_pow(base, exp, mod):
    result = 1
    while exp > 0:
        if exp % 2 == 1:
            result = result * base % mod
        exp //= 2
        base = base * base % mod
    return result

def fermat_sqrt(a, mod):
    if a == 0:
        return 0

    if a == 1:
        return 1

    n = mod - 1
    root = pow(a, (n + 1) // 2) % mod
    while not root**2 % mod == a:
        root = (root * root) % mod
    return root

def fast_mod_div(a, b, mod):
    return (a * mod_pow(b, mod - 2, mod)) % mod

def count_ways(n):
    if n <= 2:
        return 1
    if n <= 3:
        return 6
    total = 2
    for i in range(4, n + 1, 2):
        LCM = lcm(6, i)
        total = (total * LCM) % 998244353

    C6, C65 = comb(6, 1, mo=998244353), comb(6, 5, mo=998244353)

    for i in range(7, n + 1, 2):
        C65 = C65 * C65 % 998244353
        LCM = lcm(i, 6)
        C6 -= C65 * fast_mod_div(C65, LCM, 998244353) % 998244353
        C6 %= 998244353
        if C6 < 0:
            C6 += 998244353

    answer = fast_mod_div(1004248708, mod_pow(2, (n + 1) // 2, 998244353), 998244353)

    return (answer * C65) % 998244353

