MOD = 998244353

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1) % MOD

def inv(a):
    return pow(a, MOD - 2, MOD)

def pascal_triangle(n):
    levels = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1):
            if j == 0 or j == i:
                levels[i].append(1)
            else:
                levels[i].append(levels[i-1][j-1] + levels[i-1][j])
    return levels

def count_ways(n):
    edges = n * (n-1) // 2
    result = 1
    edges_left = edges - 2

    for _ in range(edges_left):
        ans = factorial(edges_left) * inv(edges_left + n - 1) % MOD * factorial(edges - 2) * inv(edges - 2 - n + 1)
        result = (result + ans) % MOD
        edges_left -= 1

    return result

