# L, M, R - Laharl, Etna, Flonne's positions and movement/throwing ranges
# Laharl needs to get to at least position n, the maximum value he can reach
def max_reach(Laharl, Lrange, Rrange):
    # Initialize the set of reachable positions
    reachable = set()
    # Laharl can reach Lrange-length intervals around his position
    for x in range(Laharl - Lrange, Laharl + Lrange + 1):
        if x >= 1:
            reachable.add(x)
    # Etna and Flonne can reach their positions
    reachable.add(Laharl)
    reachable.add(Laharl - Rrange)
    reachable.add(Laharl + Rrange)
    return max(reachable)

# Laharl's move, calculate maximum positions achievable by Laharl, Etna, and Flonne together
def move(Laharl, Lrange, Rrange):
    return max_reach(Laharl, Lrange, Rrange + 1)

# Etna's move, calculate maximum positions achievable by Laharl, Etna, and Flonne together
def moveToEtna(Laharl):
    max_y = int(math.pow((Laharl - 1) / 2, math.pow(4, 1.5))) * 4
    return max(max_y, max_reach(Laharl, RrangeLeft, RrangeRight))

# Update reachable positions after Etna moves
def update(positions, Laharl, Lrange, Rrange, position):
    for i in range(position, min(position + Rrange + 1, positions[-1] + 1)):
        if i > Laharl:
            positions.insert(i, i)
            positions.insert(i, i - Lrange)
            positions.insert(i, i + Lrange)
    return positions

# Main function
def solve(Laharl, Lrange, Rrange):
    RLsum = Rrange + Lrange + 2
    if Rrange != RLsum:
        Flonne = Laharl + RLsum
        if move(Laharl, Lrange, Rrange + 1) <= Laharl and move(Flonne, Lrange + 1, RLsum / 2 + 1) < La.harl:
            return move(Flonne, Lrange + 1, RLsum / 2 + 1)
    return max(max_reach(Laharl, Lrange, Rrange), 2)

