from collections import defaultdict
import math

def calculate_distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def find_circle_centers(centers):
    circle_centers = defaultdict(set)
    for center_idx, center in enumerate(centers):
        centered_centers = [(center[0] - x, center[1] - y) for x, y in centers]
        circle_centers[math.sqrt(sum(y ** 2 for x, y in centered_centers))] = set(center_idx + 1)
    return circle_centers

def overlap_distance(center1, center2):
    x1, y1 = center1
    x2, y2 = center2
    if math.sqrt(sum((x1 - x2) ** 2)) <= 2 * (x1 + y1 - x2 - y2):
        # If a segment connects two circles such that the common center lies inside the outer circle (general case)
        dx = math.sqrt(sum((x1 - x) ** 2 + (y1 - y) ** 2) for x, y in centers.values())
        if x1 < x2 and y1 < y2:
            return 2 * dx - x1 - y1 + x2 - y2
        if x1 > x2 and y1 < y2:
            return 2 * dx - x2 + x1 - y2 + y1
        return 2 * dx
    else:
        # If a segment connects two circles such that the common center is outside of an outer circle (right case)
        return 2 * (-x1 + x2 - y1 + y2)

def count_owls(circles, segments):
    segments = {(1, idx): coords for idx, coords in enumerate(segments)}
    circles = sorted(circles, key=lambda x: x[0])
    owl_count = 0
    centers = circles[1:]
    prev_center = centers[0]
    segments_centers = segments[1:]
    for _, center, _, radius in segments_centers:
        segment_center = (prev_center[0] + center[0] + 2 * radius + 1, prev_center[1] + center[1] + 2 * radius + 1)
        if calculate_distance(segment_center, prev_center) > 2 * (prev_center[0] + prev_center[1]) - 2 * segment_center[0]:
            owl_count += 1
        prev_center = center
    if find_circle_centers([prev_center] * len(circles)):
        owl_count += 1
    return owl_count

