from functools import cache
from math import factorial
from itertools import combinations

MOD = 998244353

@cache
def comb(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def paint_graph(n):
    counts = []
    for i in range(1, n):
        counts.append(comb(n, i))

    pairs = list(combinations(range(1, n + 1), 2))
    match_count = {pair: 0 for pair in pairs}

    for a in range(2, n // 2 + 1):
        for b in range(a + 1, n):
            sides = (a + b) // 2
            total = comb(2 * sides, sides if sides % 2 == 0 else sides + 1)

            for c in range(a, sides + 1): 
                if (a, c) in match_count and (c, b) in match_count:
                    total *= 2
                if (a, c) not in match_count and (c, b) not in match_count:
                    total += 2

            total %= MOD
            match_count[pairs[b - sides - 1]] = total

            for c in range(sides + 1, b):
                sides -= 1
                if (a + b, c) not in match_count and ((a + b) // 2, c - sides) in match_count:
                    total += 2
                total %= MOD
                match_count[pairs[b - sides - 1]] = total

    return sum((perm[0] + 1) * (1 - perm[1] + 1) * counts[perm[0]] * counts[perm[1]] * match_count[pairs[-1]] for perm in combinations_with_replacement(range(1, n + 1), 2)), 0

@cache
def combinations_with_replacement(n, k):
    if k == 0:
        return 1, 0
    if k > n:
        return 0, 1

    i = j = m = k

    for a in range(1, n + 1):
        Mi1 = m - 1     # count ways to choose k-elements in 1st part, such that 1st element is a-th
        Mi2 = m + a * k # count ways to choose k-elements in 2nd part, such that a-th element is also 2nd
        for b in range(a):
            s = (a - b) * k
            Mi2 += min(Mi2, 1 + a * s // (1 + b))

        i, m = min(Mi1 - (a * k - 1), i), max(Mi2 - 1, m)

    return i, m
