import sys

def min_destruction_time():
    mapp = {}
    for _ in range(m):
        v, u, c, t = map(int, input().split())
        if c in mapp:
            sizes = mapp[c]
        else:
            sizes = []
            mapp[c] = sizes
        if v not in sizes or u not in sizes:
            sizes.append({v, u})
        else:
            sizes[names[sizes.index(c)][0]].add(v)
            sizes[names[sizes.index(c)][1]].add(u)

    for nlist in sorted(mapp.values(), key=lambda t: (-len(t), t)):
        if nlist[names.index('0', -1)].issubset(nlist[names.index('1', -1)]):
            return n - 1, n + 1
    return 'No'

if __name__ == "__main__":
    n, m = map(int, sys.stdin.readline().split())
    input()
    names = sys.stdin.readline().split()

    print('Yes')
    print(min_destruction_time())
    print(min_destruction_time()[0])
    for c in sorted(min_destruction_time()[1]):
        print(c, end=' ')
