import sys
input = sys.stdin.readline
from collections import Counter

def main():
    n, m = map(int, input().split())
    segments = [tuple(map(int, input().split())) for _ in range(n)]
    circles = [tuple(map(int, input().split())) for _ in range(m)]

    # Count unique segment-circle pairs
    segment_pairs = set()
    for s1, s2 in segments:
        for s3, s4 in segments:
            if s3 != s4 and s1 < s2 < s3 < s4:
                segment_pairs.add(tuple(sorted([s1, s2, s3, s4])))

    # Count unique circles and their pairs
    circle_pairs = Counter()
    for c1, c2, c3 in circles:
        circle_pairs[(c1, c2)].add((c1, c2, c3))

    total_owls = 0
    # Count unique owls based on segment-circle pairs
    for s1, s2, s3, s4 in segment_pairs:
        for (c1, c2), pairs in circle_pairs.items():
            # Check if circles are symmetrical
            if (s1, s2, c1, c2) in pairs and (s3, s4, c1, c2) in pairs:
                total_owls += 1

    print(total_owls)

if __name__ == "__main__":
    main()
